-- FieldVerify：id 是技术主键，verify 是唯一业务键，绝不互换。
SET @sql=IF(EXISTS(SELECT 1 FROM `fun_field_verify` GROUP BY `verify` HAVING COUNT(*)>1),'SELECT * FROM `schema_integrity_error_030_duplicate_field_verify_verify`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @field_verify_unique=EXISTS(SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_field_verify' AND NON_UNIQUE=0 GROUP BY INDEX_NAME HAVING COUNT(*)=1 AND MAX(COLUMN_NAME='verify')=1);
SET @sql=IF(@field_verify_unique,'DO 0','ALTER TABLE `fun_field_verify` ADD UNIQUE KEY `uk_field_verify_verify` (`verify`)'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

